"use client";

import type { VendorDashboardSnapshot } from "@mealhrs/domain";
import { formatMoney } from "@mealhrs/domain";
import { ArrowUpRight, CalendarDays, CircleDollarSign, ClipboardList, Film, Store } from "lucide-react";
import Link from "next/link";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Status } from "@/components/ui/status";

export function VendorOverviewView({ snapshot }: Readonly<{ snapshot: VendorDashboardSnapshot }>) {
  const [acceptingOrders, setAcceptingOrders] = useState(snapshot.vendor.acceptsOrders);
  const cards = [
    { label: "Today’s sales", value: formatMoney(snapshot.overview.todaySales), hint: "Frontend preview", icon: CircleDollarSign },
    { label: "Needs attention", value: String(snapshot.overview.openImmediateOrders), hint: "Immediate order", icon: ClipboardList },
    { label: "Upcoming drops", value: String(snapshot.overview.upcomingMealDrops), hint: "Pre-order planning", icon: CalendarDays },
    { label: "Active stories", value: String(snapshot.overview.activePosts), hint: "Food content", icon: Film },
  ] as const;
  const nextOrder = snapshot.immediateOrders.find((order) => order.orderStatus === "pending_vendor") ?? snapshot.immediateOrders[0];
  return <div className="vendor-page"><header className="vendor-page-head"><div><p className="vendor-eyebrow">Good afternoon, Amaka</p><h1>Kitchen overview</h1><p>Keep today&apos;s service calm, clear and on time.</p></div><div className="vendor-presence"><Status tone={acceptingOrders ? "success" : "neutral"}>{acceptingOrders ? "Accepting orders" : "Orders paused"}</Status><Button size="sm" variant="secondary" onClick={() => setAcceptingOrders((current) => !current)}>{acceptingOrders ? "Pause orders" : "Resume orders"}</Button></div></header><section className="vendor-metrics" aria-label="Kitchen performance">{cards.map(({ hint, icon: Icon, label, value }) => <article className="vendor-metric" key={label}><span className="vendor-metric-icon"><Icon aria-hidden="true"/></span><p>{label}</p><strong>{value}</strong><small>{hint}</small></article>)}</section><div className="vendor-overview-grid"><section className="vendor-panel"><div className="vendor-panel-head"><div><p className="vendor-eyebrow">Next action</p><h2>{nextOrder ? `Order ${nextOrder.reference}` : "No orders need attention"}</h2></div><Link href="/vendor/orders" aria-label="View all orders"><ArrowUpRight aria-hidden="true"/></Link></div>{nextOrder ? <><div className="vendor-order-summary"><div><strong>{nextOrder.customer.name}</strong><span>{nextOrder.items.map((item) => `${item.quantity}× ${item.name}`).join(" · ")}</span></div><Status tone={nextOrder.orderStatus === "pending_vendor" ? "warning" : "success"}>{nextOrder.orderStatus.replaceAll("_", " ")}</Status></div><p className="vendor-muted">{nextOrder.fulfillmentMode === "delivery" ? "Delivery" : "Pickup"} · {nextOrder.fulfillmentWindow}</p><Button asChild block><Link href="/vendor/orders">Review order</Link></Button></> : null}</section><section className="vendor-panel"><div className="vendor-panel-head"><div><p className="vendor-eyebrow">Storefront</p><h2>What customers see</h2></div><Link href="/vendor/storefront" aria-label="Edit storefront"><ArrowUpRight aria-hidden="true"/></Link></div><div className="vendor-storefront-preview"><Store aria-hidden="true"/><div><strong>{snapshot.storefront.displayName}</strong><span>{snapshot.storefront.publicArea} · {snapshot.storefront.acceptsOrders ? "Open now" : "Paused"}</span></div></div><p className="vendor-muted">Review your public description, availability and ordering details before customers see them.</p><Button asChild variant="secondary" block><Link href="/vendor/storefront">Preview storefront</Link></Button></section></div><section className="vendor-panel vendor-quick-panel"><div><p className="vendor-eyebrow">Quick actions</p><h2>Manage today</h2></div><div className="vendor-quick-actions"><Link href="/vendor/menu">Update menu<ArrowUpRight aria-hidden="true"/></Link><Link href="/vendor/drops">Plan a Meal Drop<ArrowUpRight aria-hidden="true"/></Link><Link href="/vendor/content">Create a food story<ArrowUpRight aria-hidden="true"/></Link></div></section><p className="vendor-preview-note">All operational changes in this workspace are frontend previews. No customer order, payout, or storefront data is changed.</p></div>;
}
